#define PI (3.14159265)
#define PI_2 (PI * 2.0)

#define INV_LERP(a, b, x) (((x) - (a)) / ((b) - (a)))
#define OSCILLATE(t) ((sin((t) * (3.1415927 / 2.0)) * 0.5) + 0.5)
#define SMOOTH(x) smoothstep(0.0, 1.0, x)
#define SMOOTH2(x) SMOOTH(SMOOTH(x))

//If t is below a, caps it at 0.
//Otherwise, remaps it linealy to output 0 at t=a, and 1 at t=1.
float SmoothThreshold(float t, float a)
{
    return max(0.0, INV_LERP(a, 1.0, t));
}
//Applies a smooth threshold at 'smooth' and then a hard floor at 'harsh'.
float Threshold(float t, float smoooth, float harsh)
{
    return step(smoooth, t) * max(harsh, INV_LERP(smoooth, 1.0, t));
}

float LerpTri(float a, float b, float c, float t)
{
    if (t < 0.5)
        return mix(a, b, INV_LERP(0.0, 0.5, t));
    else
        return mix(b, c, INV_LERP(0.5, 1.0, t));
}
vec3 LerpTri(vec3 a, vec3 b, vec3 c, float t)
{
    if (t < 0.5)
        return mix(a, b, INV_LERP(0.0, 0.5, t));
    else
        return mix(b, c, INV_LERP(0.5, 1.0, t));
}
float LerpExp(float eMax, float t)
{
    return LerpTri(1.0/eMax, 1.0, eMax, t);
}

//Taken from IQ
vec3 HsvToRgb(in vec3 c)
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );

	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	

	return c.z * mix( vec3(1.0), rgb, c.y);
}
//Source: https://gist.github.com/sugi-cho/6a01cae436acddd72bdf
vec3 RgbToHsv(vec3 c){
	vec4 K=vec4(0.,-1./3.,2./3.,-1.),
	     p=mix(vec4(c.bg ,K.wz),vec4(c.gb,K.xy ),step(c.b,c.g)),
	     q=mix(vec4(p.xyw,c.r ),vec4(c.r ,p.yzx),step(p.x,c.r));
	float d=q.x-min(q.w,q.y),
	      e=1e-10;
	return vec3(abs(q.z+(q.w-q.y)/(6.*d+e)),d/(q.x+e),q.x);
}


