const float FovScale = 2.0;
const vec3 CamPos = vec3(-1.5, 0, .4);

const vec3 CamDir = vec3(1, 0, 0);
const vec3 CamRight = vec3(0, 1, 0);
const vec3 CamUp = vec3(0, 0, 1);

//////////////////////////////////////////

const vec2 StarsTwinkleSpeed = 0.001 * vec2(0.82, 1.);

const float DustCoarseSize = 20.0,
            DustFineSize = 5.5; //Relative to coarse

//////////////////////////////////////////

const float SunRotationSpeed = 0.30;

vec3 ToSun()
{
    float a = iTime * SunRotationSpeed;
    return normalize(vec3(-1, -1, 1.5) * mat3(
        1, 0, 0,
        0, cos(a), sin(a),
        0, -sin(a), cos(a)
    ));
}
const vec3 SunColor = vec3(1.0, 0.88, 0.78);

//////////////////////////////////////////

const int DustLightingIterations = 10;
const float DustShadowDistanceScale = 2.0;
const float DustShadowStepCurve = 1.5;

//Valid values are 0-2.
//Toggle the outer #if to see the different lighting models for dust.
#if 1
    #define DUST_LIGHTING_MODEL 0
#else
    #define DUST_LIGHTING_MODEL int(floor(fract(iTime*0.8 / 3.0) * 3.0))
#endif


//////////////////////////////////////////

#define HIDE_PLANET 0

const float PlanetRadius = 1.0;

const float CloudMoveSpeed = 0.006;
const float CloudShiftSpeed = 0.004;

const float PlanetShadowHeights = 0.01;
const float PlanetShadowDistanceShrink = 20.0;
const float PlanetShadowDistanceTightness = 1.0;
const int PlanetShadowIterations = 20;


//////////////////////////////////////////

const float VignetteStrength = 0.3;
//Toggle the below block to see the difference that vignette makes.
#if 1
    #define USE_VIGNETTE true
#else
    #define USE_VIGNETTE (fract(iTime/1.5) > 0.5)
#endif

