struct SurfacePoint
{
    vec3 pos, normal;
    vec2 surfaceUV;
    vec3 toCam;
};
SurfacePoint GetSurfacePoint(vec3 pos)
{
    SurfacePoint p;
    p.pos = pos;
    p.normal = normalize(p.pos);
    p.surfaceUV = vec2(dot(p.pos, CamRight), dot(p.pos, CamUp));
    p.toCam = normalize(CamPos - p.pos);
    return p;
}


struct Atmosphere
{
    float thickness;
    vec3 color;
};
Atmosphere GetAtmosphere(float normalFacingCamera, vec3 toCam,
                         float shadowAttenuation)
{
    Atmosphere a;

    a.thickness = 1.0 - normalFacingCamera;
    a.thickness = pow(a.thickness, 5.0);

    float sunFacing = max(0.0, dot(toCam, ToSun()));
    a.color = mix(
        3.0 * vec3(0.3, 0.3, 1.0),
        vec3(0.2, 0.1, 0.0),
        sunFacing * (1.0 - shadowAttenuation)
    );

    return a;
}


