vec3 StarsColor(vec2 pixel)
{
    vec2 tinyUV = pixel / iChannelResolution[0].xy;

    vec2 starsDomainWarp = textureLod(iChannel3, pixel / iChannelResolution[3].xy, 0.0).rg; //Noise(tinyUV/16.0 + 0.55 + (iTime*StarsTwinkleSpeed/10.0)).rg;
    vec4 starsA = NoiseSnapped(tinyUV),
         starsB = Noise(tinyUV/1.0 +
                        (0.1 * starsDomainWarp) +
                        (iTime * StarsTwinkleSpeed));

    float stars = (starsA.x + pow(starsB.x, 2.4)) / 2.0;

    float starsPresence = mix(0.8, 0.7,
        Noise(tinyUV/4.0 + 0.143).r
    );
    stars = clamp(INV_LERP(starsPresence, 1.0, stars), 0.0, 1.0);

    stars = pow(stars, 0.5);

    return vec3(stars);
}

