vec4 DustColor(vec2 pixel)
{
    float dustMask = DustMask(pixel, false);

    vec3 dustColor = textureLod(iChannel1,
        ((pixel / iResolution.x) / 100.0) +
        (vec2(0.6, 1.0) * iTime) /
           900.0,
    0.0).rgb;

    //Appoximate volumetric scattering by sampling dust density towards the sun.
    //The denser that dust, the more blocked we are from sunlight.
    vec3 toSun = ToSun();
    vec2 deltaPixelTowardsSun = normalize(0.000000001 +
        vec2(dot(CamRight, toSun),
             dot(CamUp, toSun))
    );
    float totalShadowDistance = (DustCoarseSize) * DustShadowDistanceScale;
    float stepShadowDistance = totalShadowDistance / float(DustLightingIterations);
    float totalShadowMass = 0.0;
    vec2 firstShadowPixel = pixel,
         lastShadowPixel = pixel + (deltaPixelTowardsSun * totalShadowDistance);
    float stepImportance = 1.0;
    for (int i = 0; i < DustLightingIterations; ++i)
    {
        //The first few steps should stay close to where we started,
        //    then start traveling farther to look at broad shadows in the distance.
        float stepT = float(i + 1) / float(DustLightingIterations),
              previousStepT = float(i) / float(DustLightingIterations);
        stepT = pow(stepT, DustShadowStepCurve);
        previousStepT = pow(previousStepT, DustShadowStepCurve);

        vec2 shadowPixel = mix(firstShadowPixel, lastShadowPixel, stepT);
        float stepSizeT = stepT - previousStepT;

        //Sample and filter the dust density at this pixel.
        float shadowSample = DustMask(shadowPixel, true),
              shadowMass = shadowSample * stepSizeT;
        totalShadowMass += pow(stepImportance * shadowMass,
                               1.0);

        //Once we get to an empty area of space, count that as immediately visible to sunlight.
        stepImportance *= pow(shadowSample, 0.0001);
    }
    //Divide shadow mass by total step distance, but step distance is in normalized units so it's 1.
    float shadowAttenuation = 1.0 - exp(-totalShadowMass * 1.4);

    //Alternative lighting models:
    if (DUST_LIGHTING_MODEL == 0)
    {
        //Come up with normalized weights
        //    for the different cases the dust can be in,
        //    and sum those cases together.

        //Brightly-lit:
        float maskLit = pow(
            pow(1.0 - shadowAttenuation, 2.0) *
              SMOOTH(pow(dustMask, 0.48)),
            0.85
        );
        //Deep inside thick dust:
        float maskInside = (1.0 - maskLit) *
                           pow(dustMask, 0.5);
        //No dust:
        float maskEmpty = (1.0 - maskLit - maskInside) *
                          pow(1.0 - dustMask, 8.0);
        //Behind thicker dust:
        float maskShadowed = 1.0 - maskLit - maskInside - maskEmpty;

        //Visualizations for the above values.
        //return vec4(dustMask, shadowAttenuation, 0, 1);
        //return vec4(maskInside, maskLit, maskShadowed, 1);

        return vec4(
            //Lit dust is extra bright.
            ((dustColor + (SunColor * 2.0)) * maskLit) +
            //Thick dust obscures anything behind it.
            (dustColor * mix(1.0, -5.0, maskInside) * maskInside) +
            //Shadowed areas display a darkened version of the dust. 
            (dustColor * 0.1 * maskShadowed),
           1.0 - maskEmpty
        );
    }
    else if (DUST_LIGHTING_MODEL == 1)
    {
        //Add sunlight to the dust based on how much it is in shadow.

        vec3 litColor = dustColor +
                        (SunColor * 10.0 * pow(shadowAttenuation, 1.2));
        return vec4(litColor, dustMask);
    }
    else if (DUST_LIGHTING_MODEL == 2)
    {
        vec3 litColor = mix(
            dustColor,
            SunColor,
            (shadowAttenuation * 5.0) - (5.0*pow(dustMask, 1.1))
        );
        return vec4(litColor, dustMask);
    }
    else
    {
        return vec4(1, 0, 1, 1);
    }
}

vec3 SpaceColor(vec3 fromCam, vec2 pixel, float planetCloseness)
{
    vec3 stars = StarsColor(pixel);
    vec4 dust = DustColor(pixel);

    //Simulate a little atmosphere just off the surface of the planet.
    //The numbers I plug in here aren't totally accurate but they look really good!
    Atmosphere atmo = GetAtmosphere(pow(1.0 - planetCloseness, 0.95),
                                    -fromCam, 0.0);

    vec3 color = mix(
        stars + (dust.rgb * dust.a),
        atmo.color,
        #if HIDE_PLANET
            0.0
        #else
            atmo.thickness
        #endif
    );

    //Add the sun.
    float sunStrength = pow(max(0.0, dot(fromCam, ToSun())), 8.0);
    color += SunColor * sunStrength;

    return color;
}


////////////////////////////////////////////

struct Clouds
{
    float Height, Strength;
};
Clouds CloudState(SurfacePoint p)
{
    Clouds state;

    vec4 n1 = MultiNoise(
        p.surfaceUV/15.0 + 0.24,
        4, 2.0,
        0.4545 + (iTime * CloudMoveSpeed)
    );
    vec4 n2 = MultiNoiseRidge(
        p.surfaceUV * n1.rg / 30.0,
        1, 2.0,
        0.88888 + (iTime * CloudShiftSpeed)
    );
    vec3 n22 = RgbToHsv(n2.rgb);

    float strength1 = clamp(n22.r / max(n22.g, n22.b), 0.0, 1.0),
          strength2 = pow(min(n22.r, min(n1.a, n1.g)),
                          LerpExp(1.4, n1.b));
    state.Strength = Threshold(strength1 * strength2, 0.35, 1.0);

    state.Height = 1.0;

    return state;
}

float BiomeMask(SurfacePoint p)
{
    //I thought this was a neat idea:
    //    generate RGB noise, then convert to HSV.
    //While each channel of the RGB noise was extremely similar,
    //    HSV has a totally different quality in each channel.
    vec4 biomeMask4 = MultiNoiseRidge(p.surfaceUV / 50.0, 5, 2.0, 0.3);
    biomeMask4.rgb = RgbToHsv(biomeMask4.rgb);
    float biomeT = biomeMask4.x *
                   pow(biomeMask4.y,
                       LerpExp(0.1, pow(biomeMask4.z, 0.2)));

    //Snap to 0 (ocean), 0.5 (plains), or 1.0 (mountains).
    //At one point I tried keeping it slightly smooth, but it didn't look good.
    biomeT = max(0.0, floor(biomeT * 3.0 - 0.00001)) / 3.0;
    biomeT /= (1.0 - (1.0 / 3.0));

    return biomeT;
}

float OceanHeight(SurfacePoint p)
{
    return 0.0;
}
vec3 OceanColor(SurfacePoint p)
{
    //Create some noise.
    vec4 n1 = MultiNoise(
        p.surfaceUV/0.4 + 0.24,
        2, 2.0,
        0.669 + (iTime * CloudMoveSpeed)
    );
    vec4 n2 = MultiNoiseRidge(
        p.surfaceUV * n1.rg / 30.0,
        1, 2.0,
        0.32223 + (iTime * CloudShiftSpeed)
    );
    vec3 n22 = RgbToHsv(n2.rgb);

    float specular = dot(ToSun(), reflect(-p.toCam, p.normal));
    specular = clamp(specular, 0.0, 1.0);
    specular = pow(specular, 8.0);

    vec3 baseColor = vec3(0.2, 0.385, 1.0);
    return baseColor + (SunColor * specular);
}

struct Plains
{
    float Plain, Height;
    float IceLevel, IceMask;
};
Plains PlainsState(SurfacePoint p)
{
    Plains state;

    //Use my HSV noise trick again.
    vec4 nRaw = MultiNoise(p.surfaceUV / 10.0, 10, 1.4, -0.1);
    vec4 n = vec4(RgbToHsv(nRaw.rgb), nRaw.a);
    state.Plain = pow(mix(n.b, n.g, n.r),
                      LerpExp(2.0, n.a));
    state.Height = mix(0.0, 0.2, state.Plain);

    //Add ice near the poles.
    float arcticNoise = MultiNoise(
        atan(p.normal.x, p.normal.y) * 0.05 * vec2(1),
        3, 3.0, 0.5221
    ).g;
    state.IceLevel = pow(abs(p.normal.z),
                         mix(2.1, 2.7, arcticNoise));
    state.IceMask = step(0.5, state.IceLevel);
    state.Height = mix(state.Height, 0.3, state.IceMask);

   return state;
}
vec3 PlainsColor(SurfacePoint p, Plains myState)
{
    vec3 color = LerpTri(
        vec3(1.0, 1.0, 0.4),
        vec3(0.2, 0.5, 0.05),
        vec3(0.1, 1.0, 0.1),
        myState.Plain
    );

    //Add ice near the poles.
    float iceBorder = clamp(1.0 - distance(0.5, myState.IceLevel), 0.0, 1.0);
    vec3 iceColor = mix(
        vec3(0.9, 0.9, 1.0),
        vec3(0.4, 0.4, 1.0),
        pow(iceBorder, 16.0)
    );
    color = mix(color, iceColor, myState.IceMask);

    return color;
}

struct Mountains
{
    float Height;
};
Mountains MountainsState(SurfacePoint p)
{
    Mountains m;

    vec4 n1 = MultiNoise(p.surfaceUV / 16.0, 7, 2.0, 0.23333);

    m.Height = 0.58 + (0.41 * (-0.5 + n1.a));

    return m;
}
vec3 MountainsColor(SurfacePoint p, Mountains myState)
{
    return mix(
        vec3(0.5, 0.35, 0.1),
        vec3(0.4, 0.1, 0.0),
        pow(OSCILLATE(myState.Height * 200.0), 0.2)
    );
    return vec3(0.4, 0.1, 0.0);
}


