float PlanetHeight(SurfacePoint p)
{
    Clouds clouds = CloudState(p);
    if (clouds.Strength > 0.9999)
        return clouds.Height;

    float biomeT = BiomeMask(p);
    if (biomeT < 0.25)
        return OceanHeight(p);
    else if (biomeT < 0.75)
        return PlainsState(p).Height;
    else
        return MountainsState(p).Height;
}
vec4 PlanetShadowAttenuation(float startingHeight, SurfacePoint p)
{
    //March towards the sun, sampling height as we go,
    //    seeing if the ray hits something.

    vec3 toSun = ToSun();

    //At a glancing sun angle, we might want to step across 1/3 of the planet's radius.
    //At a direct sun angle, we don't need to step at all (so the desired length is 0).
    float lambert = max(0.0, dot(toSun, p.normal));
    float totalLength = (PlanetRadius / PlanetShadowDistanceShrink) *
                        pow(1.0 - lambert, PlanetShadowDistanceTightness);
    float stepLength = totalLength / float(PlanetShadowIterations);

    //Initialize the march, and hold onto the first sample
    //    so we can later compute normals with it and a perpendicular sample.
    vec3 stepPos = p.pos + (toSun * stepLength);
    float marchHeight = length(stepPos);
    SurfacePoint stepP = GetSurfacePoint((stepPos / marchHeight) * PlanetRadius);
    float firstStepHeight = PlanetHeight(stepP);

    float stepHeight = firstStepHeight;
    float minDepth = 999999.0;
    float averageDepth = 0.0;
    for (int i = 0; i < PlanetShadowIterations; ++i) {
        float surfaceHeight = (stepHeight * PlanetShadowHeights),
              probeHeight = (marchHeight + startingHeight - PlanetRadius) * PlanetShadowHeights;
        float depth = probeHeight - surfaceHeight;

        minDepth = min(depth, minDepth);
        averageDepth += depth;

        stepPos += (toSun * stepLength);
        marchHeight = length(stepPos);
        stepP = GetSurfacePoint((stepPos / marchHeight) * PlanetRadius);
        stepHeight = PlanetHeight(stepP);
    }
    averageDepth /= float(PlanetShadowIterations);

    //Grab a sample perpendicular to the light direction and calculate normals.
    vec3 perpDir = normalize(cross(toSun, p.normal)),
         perp2Dir = cross(perpDir, p.normal); //The direction of the original step
    vec3 perpStepPos = p.pos + (perpDir * stepLength);
    float perpStepHeight = PlanetHeight(GetSurfacePoint(normalize(perpStepPos) * PlanetRadius));
    vec3 detailedNormal = normalize(
        (stepLength * p.normal / 5.0)
        + (perp2Dir / 2.0 * ((startingHeight - firstStepHeight) * PlanetShadowHeights))
        + (perpDir / length(toSun - lambert*p.normal) * ((startingHeight -perpStepHeight) * PlanetShadowHeights))
    );

    float shadowWeight = -averageDepth / PlanetShadowHeights;
    shadowWeight = clamp(shadowWeight, 0.0, 1.0);
    float shadowAtten = 1.0 - pow(shadowWeight, 0.25);

    return vec4(detailedNormal, shadowAtten);
}
vec3 PlanetColor(SurfacePoint p)
{
    Clouds clouds = CloudState(p);

    vec3 surfaceColor;
    float surfaceHeight;
    if (clouds.Strength > 0.9999)
    {
        surfaceColor = vec3(1);
        surfaceHeight = clouds.Height;
    }
    else
    {
        float biomeT = BiomeMask(p);
        if (biomeT < 0.25)
        {
            surfaceColor = OceanColor(p);
            surfaceHeight = OceanHeight(p);
        }
        else if (biomeT < 0.75)
        {
            Plains plains = PlainsState(p);
            surfaceColor = PlainsColor(p, plains);
            surfaceHeight = plains.Height;
        }
        else
        {
            Mountains mountains = MountainsState(p);
            surfaceColor = MountainsColor(p, mountains);
            surfaceHeight = mountains.Height;
        }
    }

    //Calculate shadows on the planet surface.
    vec4 lightingData = PlanetShadowAttenuation(surfaceHeight, p);
    vec3 detailedNormal = lightingData.xyz;
    float shadowAttenuation = lightingData.w;
    shadowAttenuation *= max(0.0, dot(detailedNormal, ToSun()));


    Atmosphere atmo = GetAtmosphere(max(0.0, dot(p.normal, p.toCam)), p.toCam, shadowAttenuation);
    return mix(
        mix(
            surfaceColor,
            vec3(1),
            clouds.Strength
        ) * shadowAttenuation,
        atmo.color,
        atmo.thickness
    );
}


////////////////////////////////////////////

vec3 Tonemap(vec2 pixel, vec3 color, bool isPlanet)
{
    float vignetteMask;
    vignetteMask = distance(pixel / iResolution.xy, vec2(0.5));
    vignetteMask = 1.0 - clamp(vignetteMask / 0.78, 0.0, 1.0);
    vignetteMask = pow(vignetteMask, VignetteStrength);
    if (USE_VIGNETTE)
        color *= vignetteMask;

    return color;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    float aspect = iResolution.x / iResolution.y;

    vec2 pixelWorldOffset = (uv - 0.5) / vec2(1.0, aspect);
    vec3 rayDir = normalize(
        CamDir +
        (FovScale * CamRight * pixelWorldOffset.x) +
        (FovScale * CamUp * pixelWorldOffset.y)
    );

    //Ray-Sphere intersection
    //    https://facultyweb.cs.wwu.edu/~wehrwes/courses/csci480_21w/lectures/L07/L07_notes.pdf
    vec3 cp = CamPos / PlanetRadius;
    float dp = dot(rayDir, cp),
          pp = dot(CamPos, cp);
    float det = (dp * dp) - (pp - 1.0);
    float t = -dp - sqrt(det);

    //Generate a space or planet color, based on what the ray hit.
    bool hitPlanet = (det > 0.0) && (HIDE_PLANET == 0);
    if (!hitPlanet)
    {
        fragColor.rgb = SpaceColor(rayDir, fragCoord, 1.0 - sqrt(-det));
    }
    else
    {
        vec3 planetPos = cp + (rayDir * t);
        SurfacePoint p = GetSurfacePoint(planetPos);
        fragColor.rgb = PlanetColor(p);
    }

    fragColor.rgb = Tonemap(fragCoord, fragColor.rgb, hitPlanet);
}
